// @generated by qw-codegen (crud)
// Customer menus: the page under the `demo` group (found by route_name, never by id) and
// one action row per permission, upserted by route_name / perms. Names are i18n keys: the page's in
// the module's web locale fragment (demo.customer.json), the actions' in menu.json (menu.action.*).
import { customerPerms } from '@qiwu/shared'
import type { EntityManager } from 'typeorm'
import { findRow, upsert } from '../../../db/seeds/upsert.js'

const ACTIONS: [perms: string, name: string][] = [
  [customerPerms.browse, 'menu.action.browse'],
  [customerPerms.view, 'menu.action.view'],
  [customerPerms.create, 'menu.action.create'],
  [customerPerms.modify, 'menu.action.modify'],
  [customerPerms.remove, 'menu.action.remove'],
  [customerPerms.export, 'menu.action.export'],
]

export async function seedCustomer(q: EntityManager): Promise<string[]> {
  // the group menu: one an administrator deleted skips these menus, a missing one is an error
  const parent = await findRow(q, 'iam_menu', { route_name: 'demo', kind: 'group' })
  if (!parent) throw new Error('seedCustomer: the demo menu group is missing')
  if (parent.deleted)
    return ['seed: the demo menu group was deleted: the customer menus are skipped']
  const pageId = await upsert(
    q,
    'iam_menu',
    { route_name: 'demo-customer' },
    {
      kind: 'page',
      name: 'menu.demo.customer',
      route_path: '/demo/customers',
      component: 'demo/customer/index',
      component_name: 'DemoCustomer',
      keep_alive: 1,
    },
    // written once: an administrator may move the page and change its icon and sort in the menu page
    { parent_id: parent.id, icon: 'lucide:building-2', sort_no: 50 },
  )
  for (const [i, [perms, name]] of ACTIONS.entries())
    await upsert(
      q,
      'iam_menu',
      { kind: 'action', perms },
      { parent_id: pageId, name, sort_no: (i + 1) * 10 },
    )
  return []
}
